<?php
require_once __DIR__.'/../includes/functions.php';$category=trim($_GET['category']??'');$categories=$pdo->query('SELECT DISTINCT category FROM vocabulary ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);$sql='SELECT * FROM vocabulary';$params=[];if($category!==''){$sql.=' WHERE category=?';$params[]=$category;}$sql.=' ORDER BY somali LIMIT 100';$stmt=$pdo->prepare($sql);$stmt->execute($params);$words=$stmt->fetchAll();$user=current_user();
$page_title='Vocabulary';$active_page='lessons';require __DIR__.'/../includes/header.php';
?>
<section class="page-hero"><div class="container"><span class="eyebrow">WORD BY WORD</span><h1>Grow your <em>vocabulary.</em></h1><p>Discover useful Somali words with English meanings, example sentences and audio when available.</p></div></section><section class="container content-section"><div class="filter-row"><div><span class="eyebrow">WORD COLLECTION</span><h2><?= count($words) ?> words to explore</h2></div><form class="select-filter" method="get"><label class="sr-only" for="category">Filter category</label><select id="category" name="category" onchange="this.form.submit()"><option value="">All categories</option><?php foreach($categories as $cat): ?><option value="<?= e($cat) ?>" <?= $category===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach; ?></select></form></div><div class="vocab-grid"><?php foreach($words as $word): ?><article class="vocab-card"><div class="vocab-card-top"><span class="category-label"><?= e($word['category']) ?></span><?php if($word['audio_path']): ?><button class="icon-button" type="button" data-audio="<?= url($word['audio_path']) ?>" aria-label="Play <?= e($word['somali']) ?>">▶</button><?php endif; ?></div><h3><?= e($word['somali']) ?></h3><p class="translation"><?= e($word['english']) ?></p><?php if($word['definition']): ?><p><?= e($word['definition']) ?></p><?php endif; ?><?php if($word['example_sentence']): ?><div class="example-line"><?= e($word['example_sentence']) ?></div><?php endif; ?><?php if($user): ?><button class="text-button" type="button" data-mark-progress data-item-type="vocabulary" data-item-id="<?= (int)$word['id'] ?>" data-csrf="<?= e(csrf_token()) ?>">Mark as learned</button><?php endif; ?></article><?php endforeach; ?></div><?php if(!$words): ?><div class="empty-state">No vocabulary entries in this category yet.</div><?php endif; ?></section>
